function unlocal_old(date) {
  const datestr = date.toISOString().substr(0, 10)
  const tup = datestr.split('-')
  return new Date(Number(tup[0]), Number(tup[1])-1, Number(tup[2]))
}

function unlocal_new(date) {
  const timeOffsetInMS = date.getTimezoneOffset() * 60000
  date.setTime(date.getTime() - timeOffsetInMS)
  const datestr = date.toISOString().substr(0, 10)
  const tup = datestr.split('-')
  return new Date(Number(tup[0]), Number(tup[1])-1, Number(tup[2]))
}

const epochInput = new Date(Date.UTC(2019,8,20)); // wire format: UTC midnight
console.log("getTimezoneOffset:", epochInput.getTimezoneOffset())

const oldEpoch = unlocal_old(new Date(epochInput.getTime()))
const newEpoch = unlocal_new(new Date(epochInput.getTime()))
console.log("numeric-epoch path: OLD=" + oldEpoch.toDateString() + " NEW=" + newEpoch.toDateString())

// round-trip path: value = date.toDateString() then re-parsed
const roundTripStr = new Date(2019,8,20).toDateString() // local midnight day, then toDateString
const roundTripDate = new Date(roundTripStr) // reparse -> local midnight
const oldRT = unlocal_old(new Date(roundTripDate.getTime()))
const newRT = unlocal_new(new Date(roundTripDate.getTime()))
console.log("round-trip path:    OLD=" + oldRT.toDateString() + " NEW=" + newRT.toDateString())
EOF
