function unlocal_fixed(date) {
  if (date.getUTCHours() || date.getUTCMinutes() || date.getUTCSeconds()) {
    const timeOffsetInMS = date.getTimezoneOffset() * 60000
    date.setTime(date.getTime() - timeOffsetInMS)
  }
  const datestr = date.toISOString().substr(0, 10)
  const tup = datestr.split('-')
  return new Date(Number(tup[0]), Number(tup[1])-1, Number(tup[2]))
}

const epochInput = new Date(Date.UTC(2019,8,20));
const roundTripStr = new Date(2019,8,20).toDateString()
const roundTripDate = new Date(roundTripStr)

console.log("numeric-epoch path ->", unlocal_fixed(new Date(epochInput.getTime())).toDateString())
console.log("round-trip path    ->", unlocal_fixed(new Date(roundTripDate.getTime())).toDateString())
EOF
